                    "sql": "drop table if exists public.quickshift_sales_consolidated; CREATE TABLE public.quickshift_sales_consolidated AS select s.*, wm.\"Mapped Warehouse Name\", UPPER(mm.\"Order Type\") AS \"Order Type\", mm.\"Mapped Marketplace Name\", wm.\"Client Name\", ws.mapped_warehouse_status, wm.\"facility name\", SUBSTRING( data_source, POSITION(\' \' IN data_source) + 1 ) AS \"CLIENT\", data_source AS \"data_source_2\", CASE WHEN UPPER(mm.\"order type\") = \'D2C\' THEN CASE WHEN EXTRACT(HOUR FROM COALESCE(s.inventory_assigned_date, s.order_date)) < 13 THEN DATE_TRUNC(\'DAY\',COALESCE(s.inventory_assigned_date,s.order_date)) + INTERVAL \'13 HOURS\' ELSE DATEADD( DAY, 1, DATE_TRUNC( \'DAY\',COALESCE( s.inventory_assigned_date, s.order_date) )) + INTERVAL \'13 HOURS\' END WHEN UPPER(mm.\"order type\") = \'B2B\' THEN DATEADD(day, 2, COALESCE(s.inventory_assigned_date, s.order_date)) WHEN UPPER(mm.\"order type\") = \'MARKETPLACE\' THEN COALESCE(s.inventory_assigned_date, s.order_date) END AS Expected_Completed_Date, CAST(CASE WHEN UPPER(mm.\"order type\") = \'D2C\' THEN CASE WHEN EXTRACT(HOUR FROM COALESCE(s.fulfillment_tat, s.order_date)) < 13 THEN DATE_TRUNC(\'DAY\',COALESCE(s.fulfillment_tat,s.order_date)) + INTERVAL \'13 HOURS\' ELSE DATEADD( DAY, 1, DATE_TRUNC( \'DAY\',COALESCE( s.fulfillment_tat, s.order_date) )) + INTERVAL \'13 HOURS\' END WHEN UPPER(mm.\"order type\") = \'B2B\' THEN DATEADD(day, 2, COALESCE(s.inventory_assigned_date, s.order_date)) WHEN UPPER(mm.\"order type\") = \'MARKETPLACE\' THEN COALESCE(s.fulfillment_tat, s.order_date) END AS DATE)AS Acheived_Date, CASE WHEN cast(dispatch_date as date) <= CAST((CASE WHEN UPPER(mm.\"order type\") = \'D2C\' THEN CASE WHEN EXTRACT(HOUR FROM COALESCE(s.fulfillment_tat, s.order_date)) < 13 THEN DATE_TRUNC(\'DAY\', COALESCE(s.fulfillment_tat, s.order_date)) + INTERVAL \'13 HOURS\' ELSE DATEADD(DAY,1,DATE_TRUNC(\'DAY\', COALESCE(s.fulfillment_tat, s.order_date))) + INTERVAL \'13 HOURS\' END WHEN UPPER(mm.\"order type\") = \'B2B\' THEN DATEADD(day, 2, COALESCE(s.inventory_assigned_date, s.order_date)) WHEN UPPER(mm.\"order type\") = \'MARKETPLACE\' THEN COALESCE(s.fulfillment_tat, s.order_date) END) AS DATE) THEN \'IN_TAT\' ELSE \'OUT_TAT\' END AS tat_status, CAST( CASE WHEN UPPER(mm.\"Order Type\") = \'B2B\' THEN aov.B2B WHEN UPPER(mm.\"Order Type\") = \'D2C\' THEN aov.D2C WHEN UPPER(mm.\"Order Type\") = \'MARKETPLACE\' THEN aov.MARKETPLACE END AS DOUBLE PRECISION) AS Revenue, CAST( CASE WHEN UPPER(mm.\"Order Type\") = \'B2B\' THEN aov.B2B WHEN UPPER(mm.\"Order Type\") = \'D2C\' THEN aov.D2C WHEN UPPER(mm.\"Order Type\") = \'MARKETPLACE\' THEN aov.MARKETPLACE END AS DOUBLE PRECISION )/NULLIF(COUNT(*) OVER (PARTITION BY reference_code), 0) AS AOV, CASE WHEN UPPER(oms_order_status) IN (\'COMPLETE\', \'SHIPPED\', \'READY TO DISPATCH\') THEN \'COMPLETED\' WHEN UPPER(oms_order_status) IN (\'ASSIGNED\', \'CREATED\') THEN \'PENDING\' ELSE \'OTHER\' END AS OMS_Status, CASE WHEN EXTRACT(HOUR FROM s.order_date) < 13 THEN CAST(DATE_TRUNC(\'DAY\', s.order_date) AS DATE) ELSE CAST(DATEADD(DAY, 1, DATE_TRUNC(\'DAY\', s.order_date)) AS DATE) END AS \"new_order_date\", CASE WHEN EXTRACT(HOUR FROM s.inventory_assigned_date) < 13 THEN CAST(DATE_TRUNC(\'DAY\', s.inventory_assigned_date) AS DATE) ELSE CAST(DATEADD(DAY, 1, DATE_TRUNC(\'DAY\', s.inventory_assigned_date)) AS DATE) END AS \"handover_date\" from public.quickshift_sales_consolidated_intermediate s left join (select * from (select *, row_number() over (partition by \"Facility Name\" order by \"Facility Name\") rw from public.Quickshift_gs_Warehouse_Mapping ) where rw = 1) wm on lower(wm.\"Facility Name\") = lower(s.warehouse) left join (select * from (select *, row_number() over (partition by \"Marketplace Name\" order by \"Marketplace Name\") rw from public.gs_marketplace_mapping ) where rw = 1) mm on lower(mm.\"Marketplace Name\") = lower(s.marketplace) left join (select * from (select \"order status\" as order_status, \"shipping status\" as shipping_status, \"warehouse status\" as mapped_warehouse_status, row_number() over (partition by \"shipping status\",\"order status\" order by 1,2) rw from public.gs_warehouse_status ) where rw = 1) ws on lower(ws.order_status) = lower(s.order_status) and lower(ws.shipping_status) = lower(s.shipping_status) LEFT JOIN ( SELECT * FROM( SELECT \"client name\" AS Client_Name, \"f b2b\" AS B2B, \"f b2c\" AS D2C, \"f b2c\" AS MARKETPLACE, ROW_NUMBER() OVER(PARTITION BY \"client name\") rw FROM public.QuickShift_Revenue_gs_Client_Wise_AOV ) where rw=1) aov ON LOWER(aov.Client_Name) = LOWER(wm.\"Client Name\") ; DROP TABLE IF EXISTS public.GS_State_ISO; CREATE TABLE public.GS_State_ISO ( state VARCHAR(256), iso_code VARCHAR(10) ); UPDATE public.quickshift_sales_consolidated SET state = CASE WHEN UPPER(state) IN (\'AP\', \'ANDHRA PRADESH\', \'ANDHRAPRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\', \'ASSAM HINDUISM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\', \'CHATTISGARH\', \'CHHATISGARH\') THEN \'CHHATTISGARH\' WHEN UPPER(state) IN (\'GA\', \'GOA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GJ\', \'GUJARAT\', \'GUJRAT\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HR\', \'HARYANA\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'HP\', \'HIMACHAL PRADESH\', \'HIMANCHAL PRADESH\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\', \'KARANATAKA\', \'KARNATKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\', \'MADHYAPRADESH\', \'M. P\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\', \'MAHARASTRA\', \'MAHARASHATRA\', \'MAHASHTRA\', \'MUMBAI THANA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\', \'MEGALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NAGALAND\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\', \'ORISSA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\', \'TAMILNADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\') THEN \'TELANGANA\' WHEN UPPER(state) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\', \'UTTER PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\', \'UTTARAKHAND\', \'UTTRAKHAND\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\', \'WEST BANGAL\', \'WB(KOLKATA & HOWRAH AREA)\') THEN \'WEST BENGAL\' WHEN UPPER(state) IN (\'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'CH\', \'CHANDIGARH\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'DN\', \'DADRA AND NAGAR HAVELI\', \'DADRA & NAGAR HAVELI\', \'DD\', \'DAMAN AND DIU\', \'DAMAN & DIU\', \'DADRA & NAGAR HAVELI AND DAMAN & DIU\', \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\', \'DADRA AND NAGAR HAV.\') THEN \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\' WHEN UPPER(state) IN (\'LD\', \'LAKSHADWEEP\') THEN \'LAKSHADWEEP\' WHEN UPPER(state) IN (\'DL\', \'DELHI\', \'NEW DELHI\', \'NCR\') THEN \'DELHI\' WHEN UPPER(state) IN (\'PY\', \'PUDUCHERRY\', \'PONDICHERRY\') THEN \'PUDUCHERRY\' WHEN UPPER(state) IN (\'JK\', \'JAMMU AND KASHMIR\', \'JAMMU & KASHMIR\') THEN \'JAMMU AND KASHMIR\' WHEN UPPER(state) = \'LADAKH\' THEN \'LADAKH\' WHEN UPPER(state) IN (\'AUCKLAND\', \'UNITED KINGDOM (+44)\', \'NON-US\', \'ZEELAND\', \'SINGAPORE\', \'BARCELONA\') THEN NULL WHEN UPPER(state) IN (\'INDIA\', \'1493\', \'BJP.TEAM211@GMAIL.COM\') THEN NULL WHEN UPPER(state) IN (\'NOT SPECIFIED\', \'\') THEN NULL ELSE state END;",
